<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Foundry\SubordinateConstructionAuthorizationAcceptanceService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:foundry:accept-subordinate-construction',description:'Have the occupied Artificer accept an exact subordinate-construction authorization')]
final class FoundryAcceptSubordinateConstructionAuthorizationCommand extends Command{public function __construct(private readonly SubordinateConstructionAuthorizationAcceptanceService $service){parent::__construct();}protected function configure():void{$this->addArgument('delivery-id',InputArgument::REQUIRED)->addArgument('binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface $input,OutputInterface $output):int{try{$a=$this->service->accept((string)$input->getArgument('delivery-id'),(string)$input->getArgument('binding-id'));}catch(\Throwable$e){$output->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if((bool)$input->getOption('json')){$output->writeln(json_encode($a,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return self::SUCCESS;}$output->writeln('<info>SUBORDINATE_CONSTRUCTION_AUTHORIZATION_ACCEPTED</info> '.$a['acceptance_id']);$output->writeln('Artificer: '.$a['actor']['manifestation_id']);$output->writeln('Disposition: '.$a['disposition']);foreach($a['authorized_resolutions']as$r)$output->writeln('- '.$r['office'].' '.$r['subordinate_staff_class'].' '.$r['resolution_id']);$output->writeln('Construction authority: EXERCISABLE FOR EXACT RESOLUTIONS');$output->writeln('Selection authority: NOT GRANTED');$output->writeln('Profile approval authority: NOT GRANTED');$output->writeln('Spawning authority: NOT GRANTED');$output->writeln('Seat binding authority: NOT GRANTED');$output->writeln('Execution authority: NOT GRANTED');return self::SUCCESS;}}
